#!/bin/bash
# Arma 3 dedicated server (Octail's own install script; pelican-eggs' egg was read as a reference only).
# App 233780 can't be downloaded anonymously: the server needs a logged-in Steam account (Bohemia: it doesn't have to own Arma 3; Workshop downloads do).
# Octail's steam_login feature fills STEAM_USER and, for this install only, STEAM_PASS; Steam Guard codes are asked
# for in the console.
set -uo pipefail

if [ -z "${STEAM_USER:-}" ] || [ "${STEAM_USER}" = anonymous ]; then
    echo "The Arma 3 server can't be downloaded anonymously: pick a Steam account on the Startup tab"
    echo "(Steam account), then reinstall the server."
    exit 1
fi
echo "Logging in to Steam as ${STEAM_USER}"

## download and install steamcmd
cd /tmp || exit 1
mkdir -p /mnt/server/steamcmd
curl -fsSL -o steamcmd.tar.gz https://steamcdn-a.akamaihd.net/client/installer/steamcmd_linux.tar.gz || exit 1
tar -xzf steamcmd.tar.gz -C /mnt/server/steamcmd || exit 1
mkdir -p /mnt/server/steamapps # Fix steamcmd disk write error when this folder is missing

## the account's saved login (Tentacle's login cache), so later updates log in without the password
if [ -n "${STEAM_LOGIN_CACHE:-}" ]; then
    rm -rf /mnt/server/steamcmd/config && ln -s "${STEAM_LOGIN_CACHE}" /mnt/server/steamcmd/config
fi
cd /mnt/server/steamcmd || exit 1

# SteamCMD fails otherwise for some reason, even running as root.
chown -R root:root /mnt/server/steamcmd /mnt/server/steamapps
export HOME=/mnt/server

LOGIN=("${STEAM_USER}")
[ -n "${STEAM_PASS:-}" ] && LOGIN+=("${STEAM_PASS}")
[ -n "${STEAM_AUTH:-}" ] && LOGIN+=("${STEAM_AUTH}")

## install the server with steamcmd (the Linux depot)
## Octail: SteamCMD's first run often fails with "Missing configuration"; try up to 3 times
for steamcmd_try in 1 2 3; do
    if ./steamcmd.sh +force_install_dir /mnt/server +login "${LOGIN[@]}" +app_update "${SRCDS_APPID}" validate +quit 2>&1 | tee /tmp/steamcmd.log && grep -q "Success! App '" /tmp/steamcmd.log && ! grep -q "ERROR! Failed to install app" /tmp/steamcmd.log; then break; fi
    echo "SteamCMD did not finish (attempt $steamcmd_try of 3)"
done

## set up 32 and 64 bit Steam client libraries
mkdir -p /mnt/server/.steam/sdk32 /mnt/server/.steam/sdk64
cp -v linux32/steamclient.so /mnt/server/.steam/sdk32/steamclient.so
cp -v linux64/steamclient.so /mnt/server/.steam/sdk64/steamclient.so

## Octail: fail the install when SteamCMD didn't download the server
if [[ ! -f "/mnt/server/arma3server_x64" ]]; then
    echo -e "\nSteamCMD failed to install the Arma 3 dedicated server. The download needs a logged-in Steam account;"
    echo "Check the login lines above, then reinstall."
    exit 1
fi
chmod +x "/mnt/server/arma3server_x64"
cd /mnt/server || exit 1

mkdir -p mpmissions keys profiles workshop
## Octail: default config files, only when there are none (a reinstall keeps yours)
if [ ! -f basic.cfg ]; then
    echo "Writing a default basic.cfg (network settings)."
    cat > basic.cfg <<'OCTAIL_EOF'
// Network settings: https://community.bistudio.com/wiki/Arma_3:_Basic_Server_Config_File
MaxMsgSend = 128;
MaxSizeGuaranteed = 512;
MaxSizeNonguaranteed = 256;
MinBandwidth = 131072;
MaxBandwidth = 10000000000;
MinErrorToSend = 0.001;
MinErrorToSendNear = 0.01;
MaxCustomFileSize = 0;
class sockets
{
    maxPacketSize = 1400;
};
OCTAIL_EOF
fi
if [ ! -f server.cfg ]; then
    echo "Writing a default server.cfg. Octail sets the name, passwords, slots, BattlEye, signatures and"
    echo "persistence before every start; missions, MOTD and the rest are yours to edit."
    cat > server.cfg <<'OCTAIL_EOF'
// Arma 3 server config: https://community.bistudio.com/wiki/Arma_3:_Server_Config_File
// Octail rewrites the lines that start with hostname, password, passwordAdmin, maxPlayers, BattlEye,
// verifySignatures and persistent before every start (the Startup tab). Keep them on one line each.
hostname = "Arma 3 server";
password = "";
passwordAdmin = "";
maxPlayers = 32;
BattlEye = 1;
verifySignatures = 2;
persistent = 1;
kickDuplicate = 1;
voteThreshold = 0.33;
voteMissionPlayers = 1;
disableVoN = 0;
vonCodecQuality = 20;
logFile = "server_console.log";
timeStampFormat = "short";
motd[] = { "Welcome to the server" };
motdInterval = 5;

// Missions: put the mission's .pbo into mpmissions/ and list it here, for example
//     class Mission1 { template = "MyMission.Altis"; difficulty = "Regular"; };
// With no mission listed, a logged-in admin picks one in game (#missions).
class Missions
{
};
OCTAIL_EOF
fi

## install end
echo "-----------------------------------------"
echo "Installation completed..."
echo "-----------------------------------------"
